"""Spectre state files (docs/VAMOS_SPECTRE_DESIGN.md §8.6 [M UG pp.203-204]; the API is the §10 block).

Written by `write=`/`writefinal=` from the full-solution saves (§5.4), read by `readns`, `readic`
and `read=`:

    # State file generated by Spectre from circuit file 'opamp.scs'
    # during 'stepresponse' at 5:39:38 PM, jan 21, 1992.
    out 1.17406247989272
    I2.Mid 0.588793510612534
    V1:p -0.001

Nets first (hierarchical with `.`), then the vsource currents (`V1:p`); 15 significant digits
(%.15g), keeping the leading zero the UG's example drops (§14 q.49).  `state_date(t)` gives the
header's date: §8.2's time, no day name, the month in lower case, the day unpadded.

Reading: `#` starts a comment; an entry whose name carries `:` is a current entry (`V1:p`), any
other a node entry.  The caller drops the current entries with one note (`readns`) or one warning
(`readic`): "<n> current entries not applied" (§8.6).
"""

from __future__ import annotations

import os
from datetime import datetime
from typing import Dict, Mapping, Tuple

_MONTHS = ("jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec")
VALUE_FORMAT = "%.15g"


def state_date(t: datetime) -> str:
    """The header's date: `5:39:38 PM, jan 21, 1992` [M UG p.204] (the time as §8.2's, no day name,
    the month in lower case, the day unpadded)."""
    hour = t.hour % 12 or 12
    return "%d:%02d:%02d %s, %s %d, %d" % (hour, t.minute, t.second, "AM" if t.hour < 12 else "PM",
                                          _MONTHS[t.month - 1], t.day, t.year)


def write(path: str, nodes: Mapping[str, float], currents: Mapping[str, float], circuit: str,
          analysis: str, date: str) -> None:
    """Write a state file (§8.6): the two-line `#` header, then `<name> <value>` per entry, the
    nodes in the given order, then the currents."""
    tmp = path + ".vamos-tmp"
    with open(tmp, "w", encoding="latin-1", newline="\n") as fh:
        fh.write("# State file generated by Spectre from circuit file '%s'\n" % circuit)
        fh.write("# during '%s' at %s.\n" % (analysis, date))
        for table in (nodes, currents):
            for name, value in table.items():
                fh.write("%s %s\n" % (name, VALUE_FORMAT % float(value)))
    os.replace(tmp, path)


def read(path: str) -> Tuple[Dict[str, float], Dict[str, float]]:
    """Read a state file: (node entries, current entries), in file order; `#` starts a comment.  A
    line that is not `<name> <number>` is a ValueError naming the file and line."""
    nodes: Dict[str, float] = {}
    currents: Dict[str, float] = {}
    with open(path, encoding="latin-1") as fh:
        for lineno, raw in enumerate(fh, 1):
            text = raw.split("#", 1)[0].strip()
            if not text:
                continue
            parts = text.split()
            if len(parts) != 2:
                raise ValueError("%s:%d: expected `<name> <value>`, got %r" % (path, lineno, raw.rstrip("\n")))
            name, value = parts
            try:
                v = float(value)
            except ValueError:
                raise ValueError("%s:%d: %r is not a number" % (path, lineno, value))
            (currents if ":" in name else nodes)[name] = v
    return nodes, currents


__all__ = ["write", "read", "state_date", "VALUE_FORMAT"]
